/* fx/hero-gl texture data. ONLY requested by fx/hero-gl.js when the page is opened straight from disk (file://):
   browsers give every file:// URL its own origin, so WebGL refuses the pixels of images loaded from disk, while a
   classic <script> still loads and data: URIs are same-origin. Over http(s) and in the standalone build (whose
   images are already data: URIs) this file is never fetched.
   Byte-identical copies of assets/hero.jpg, assets/hero-mask.png and assets/hero-gl-plate.jpg. Regenerate whenever
   one of them changes (hero-gl.js refuses a copy whose hero.jpg size no longer matches), from the project root:
     python3 - <<'PY'
     import base64, pathlib
     A = pathlib.Path('assets'); u = lambda f, t: 'data:' + t + ';base64,' + base64.b64encode((A / f).read_bytes()).decode()
     t = (A / 'hero-gl-data.js').read_text(); t = t[:t.index('*' + '/') + 2] + '\n'
     t += 'window.HERO_GL_DATA={"photo":"%s",\n"mask":"%s",\n"plate":"%s"};\n' % (u('hero.jpg', 'image/jpeg'), u('hero-mask.png', 'image/png'), u('hero-gl-plate.jpg', 'image/jpeg'))
     (A / 'hero-gl-data.js').write_text(t)
     PY
*/
window.HERO_GL_DATA={"photo":"data:image/jpeg;base64,",
"mask":"data:image/png;base64,",
"plate":"data:image/jpeg;base64,"};
